import{_ as t,o as r,c as o,a5 as d}from"./chunks/framework.BZzouRtU.js";const a="/study/images/graphics/d3d12-descriptor-heaps.svg",g=JSON.parse('{"title":"D3D12のディスクリプタヒープとテーブルを使う","description":"","frontmatter":{"title":"D3D12のディスクリプタヒープとテーブルを使う","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"リソースをビューとして参照し、ディスクリプタテーブルをシェーダへ渡す。CPUとGPUのハンドル、スロットの再利用、Root Signature 1.1の更新条件を扱う。","aliases":["D3D12","descriptor heap","descriptor table","CPU descriptor handle","GPU descriptor handle","SetDescriptorHeaps","Root Signature 1.1"],"verification":"MicrosoftのD3D12 APIリファレンスとルートシグネチャの仕様に照合"}},"headers":[],"relativePath":"graphics/optimization/d3d12-descriptor-heaps.md","filePath":"graphics/optimization/d3d12-descriptor-heaps.md"}'),s={name:"graphics/optimization/d3d12-descriptor-heaps.md"};function i(c,e,n,p,l,h){return r(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="d3d12のディスクリプタヒープとテーブルを使う" tabindex="-1">D3D12のディスクリプタヒープとテーブルを使う <a class="header-anchor" href="#d3d12のディスクリプタヒープとテーブルを使う" aria-label="Permalink to &quot;D3D12のディスクリプタヒープとテーブルを使う&quot;">​</a></h1><p>例えば、ミップマップ付きのテクスチャをシェーダから読むとします。テクスチャの<strong>リソース</strong>が画像データを保持し、<strong>ビュー</strong>が読み取るミップ範囲や形式を決めます。ビューの設定を書き込んだ<strong>ディスクリプタ</strong>は、<strong>ヒープ</strong>のスロットに並びます。一つのテクスチャに全ミップを読むSRVと、特定のミップだけを読むSRVを作れば、画像データを共有しながら用途に応じて参照範囲を変えられます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/descriptors-overview" target="_blank" rel="noreferrer">Microsoftのディスクリプタの概要</a> · <a href="/study/graphics/texture/dds-and-subresources.html">テクスチャのmipとサブリソース</a></p><h2 id="ヒープの種類で、渡す相手が決まる" tabindex="-1">ヒープの種類で、渡す相手が決まる <a class="header-anchor" href="#ヒープの種類で、渡す相手が決まる" aria-label="Permalink to &quot;ヒープの種類で、渡す相手が決まる&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ヒープの種類</th><th>格納するもの</th><th>コマンドでの使い方</th></tr></thead><tbody><tr><td><code>CBV_SRV_UAV</code></td><td>定数バッファ、読み取り用リソース、読み書き用リソースのビュー</td><td>シェーダ可視にして、ディスクリプタテーブルから参照する</td></tr><tr><td><code>SAMPLER</code></td><td>フィルタやアドレスモードなど、サンプリングの設定</td><td>シェーダ可視にして、サンプラ用テーブルから参照する</td></tr><tr><td><code>RTV</code></td><td>描画先のビュー</td><td><code>OMSetRenderTargets</code> などへCPUハンドルを渡す</td></tr><tr><td><code>DSV</code></td><td>深度・ステンシルのビュー</td><td><code>OMSetRenderTargets</code> などへCPUハンドルを渡す</td></tr></tbody></table><p><code>D3D12_DESCRIPTOR_HEAP_FLAG_SHADER_VISIBLE</code> を付けられるのは <code>CBV_SRV_UAV</code> と <code>SAMPLER</code> です。<code>SetDescriptorHeaps</code> で同時にセットできるのは各種類一つ、合計二つまでです。シェーダ可視の <code>SAMPLER</code> ヒープは最大2,048スロットです。<code>CBV_SRV_UAV</code> ヒープの容量やシェーダステージごとの参照数は、デバイスの <code>ResourceBindingTier</code> に応じて確認します。例えばTier 1ではヒープ全体に100万個を置けても、一つのシェーダステージで全テーブルを合わせて使えるSRVは128個までです。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12graphicscommandlist-setdescriptorheaps" target="_blank" rel="noreferrer">MicrosoftのSetDescriptorHeaps</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/hardware-support" target="_blank" rel="noreferrer">リソースバインディングの上限</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/ns-d3d12-d3d12_feature_data_d3d12_options" target="_blank" rel="noreferrer">デバイスの対応状況を調べる構造体</a></p><h2 id="同じスロットをcpuとgpuのハンドルで指す" tabindex="-1">同じスロットをCPUとGPUのハンドルで指す <a class="header-anchor" href="#同じスロットをcpuとgpuのハンドルで指す" aria-label="Permalink to &quot;同じスロットをCPUとGPUのハンドルで指す&quot;">​</a></h2><p><strong>CPUハンドル</strong>は <code>CreateShaderResourceView</code> などでスロットへ書き込むときに使います。<strong>GPUハンドル</strong>は、シェーダ可視ヒープの中でテーブルが始まるスロットを指定するときに使います。どちらも、ヒープ先頭のハンドルに <code>スロット番号 × GetDescriptorHandleIncrementSize(ヒープの種類)</code> を加えて求められます。この増分はデバイスに問い合わせ、ハンドルはAPIに渡して使います。アプリがハンドルの参照先を直接読み書きすることはできません。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/creating-descriptor-heaps#descriptor-handles" target="_blank" rel="noreferrer">Microsoftのハンドルの仕様</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12device-getdescriptorhandleincrementsize" target="_blank" rel="noreferrer">ハンドルの増分を取得するAPI</a></p><p>ビューはシェーダ可視ヒープに直接作成できます。CPU側でビューをまとめて管理する構成では、シェーダ非可視の保管用ヒープに作り、描画に使うものを <code>CopyDescriptorsSimple</code> などでシェーダ可視ヒープへ移します。コピーするのはビューの情報です。ビューが参照するリソースのデータは、リソース転送用のコマンドで扱います。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/setting-descriptor-heaps#populating-descriptor-heaps" target="_blank" rel="noreferrer">Microsoftのディスクリプタの初期化</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12device-copydescriptorssimple" target="_blank" rel="noreferrer">CopyDescriptorsSimpleのコピー元とコピー先</a> · <a href="/study/graphics/texture/d3d12-texture-upload.html">D3D12のテクスチャ転送</a></p><h2 id="テーブルの配置を決め、先頭をコマンドに渡す" tabindex="-1">テーブルの配置を決め、先頭をコマンドに渡す <a class="header-anchor" href="#テーブルの配置を決め、先頭をコマンドに渡す" aria-label="Permalink to &quot;テーブルの配置を決め、先頭をコマンドに渡す&quot;">​</a></h2><p><strong>ディスクリプタテーブル</strong>は、ヒープの一部を参照する仕組みです。ルートシグネチャで、テーブルを置くルートパラメータ番号と、テーブル内の種類・シェーダレジスタ・個数・オフセットを指定します。例えばルートパラメータ0に、テーブル内の位置0を <code>b0</code> のCBV、位置1と2を <code>t0</code> と <code>t1</code> のSRVに対応させます。同じレイアウトを使うフレームごとに、テーブルの先頭を変えられます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/descriptor-tables" target="_blank" rel="noreferrer">Microsoftのディスクリプタテーブル</a></p><p>記録時にルートシグネチャと <code>SetDescriptorHeaps</code> で使用するヒープをセットします。続いて <code>SetGraphicsRootDescriptorTable(0, baseGpuHandle)</code> で、ルートパラメータ0にテーブルのGPUハンドルを渡します。コンピュート用には <code>SetComputeRootDescriptorTable</code> を使います。別のヒープへ切り替えるとテーブル設定が無効になるため、使うテーブルを設定し直します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/setting-descriptor-heaps#setting-descriptor-heaps" target="_blank" rel="noreferrer">Microsoftのヒープ設定</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12graphicscommandlist-setgraphicsrootdescriptortable" target="_blank" rel="noreferrer">SetGraphicsRootDescriptorTableの引数</a></p><figure class="study-figure"><img src="'+a+'" alt="一つのシェーダ可視ヒープを二つのフレーム範囲に分ける。どちらも先頭からCBV b0、SRV t0、SRV t1の順に置く。フレームBではスロット3のGPUハンドルをテーブル先頭として渡す。フレームAは対応するフェンス値に達した後にスロット0から2を再利用する。" width="760" height="430" loading="lazy"><figcaption>テーブルの配置をそろえ、フレームごとにヒープ内の別の範囲を指す。<a href="/study/images/graphics/d3d12-descriptor-heaps.svg" target="_blank" rel="noopener noreferrer">ディスクリプタの図を拡大</a></figcaption></figure><h2 id="フレームごとにスロットを確保して再利用する" tabindex="-1">フレームごとにスロットを確保して再利用する <a class="header-anchor" href="#フレームごとにスロットを確保して再利用する" aria-label="Permalink to &quot;フレームごとにスロットを確保して再利用する&quot;">​</a></h2><p>描画ごとに参照先を変える場合は、書き換え可能な範囲をフレームごとに分けます。図ではフレームAにスロット0〜2、Bに3〜5を割り当てています。CPUはAを参照する描画を提出した後も、Bの範囲に次のビューを用意できます。Aの範囲へ戻るときは、Aを最後に参照する処理の後でキューが通知したフェンス値を確認します。複数のキューから参照される場合は、それぞれの最後の参照を追います。複数のワーカーがディスクリプタを用意する場合も、各ワーカーが書き込む範囲を先に分けておけます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/advanced-use-of-descriptor-tables#changing-descriptor-table-entries-between-rendering-calls" target="_blank" rel="noreferrer">Microsoftのテーブル更新の規則</a> · <a href="/study/graphics/optimization/gpu-resource-lifetime.html">GPUリソースと一時領域の寿命</a> · <a href="/study/graphics/optimization/parallel-command-recording.html">D3D12の並列コマンド記録</a></p><p>RTVとDSVの内容は、<code>OMSetRenderTargets</code> などを呼んだときにコマンドリストへ記録されます。この呼び出しが使ったCPU側のスロットは、呼び出しから戻れば再利用できます。ビューが参照した描画先のリソース自体は、GPUが使い終えるまで保持します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/non-shader-visible-descriptor-heaps#non-visible-views" target="_blank" rel="noreferrer">Microsoftの非シェーダ可視ヒープの仕様</a></p><h2 id="root-signature-1-1では二つの更新条件を指定する" tabindex="-1">Root Signature 1.1では二つの更新条件を指定する <a class="header-anchor" href="#root-signature-1-1では二つの更新条件を指定する" aria-label="Permalink to &quot;Root Signature 1.1では二つの更新条件を指定する&quot;">​</a></h2><p>Root Signature 1.1では、<strong>スロットに入れたディスクリプタ</strong>と、<strong>ディスクリプタが参照するデータ</strong>について、いつ変更できるかを別々に指定します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/root-signature-version-1-1#static-and-volatile-flags" target="_blank" rel="noreferrer">MicrosoftのRoot Signature 1.1仕様</a></p><table tabindex="0"><thead><tr><th>変更の対象</th><th>指定</th><th>守る期間</th></tr></thead><tbody><tr><td>ディスクリプタ</td><td>静的（<code>DESCRIPTORS_VOLATILE</code> なし。1.1の既定）</td><td>記録時にテーブルをセットするまでに用意し、そのリストの最後の実行が完了するまで保つ</td></tr><tr><td>ディスクリプタ</td><td><code>DESCRIPTORS_VOLATILE</code></td><td>記録後から提出前の差し替えも可能。提出から実行完了までは保つ</td></tr><tr><td>参照先のデータ</td><td><code>DATA_STATIC</code></td><td>記録時にバインドするまでに初期化し、最後の実行が完了するまで保つ</td></tr><tr><td>参照先のデータ</td><td><code>DATA_STATIC_WHILE_SET_AT_EXECUTE</code></td><td>GPUがそのバインドを実行した時点から、それを使う描画・ディスパッチが終わるまで保つ。更新後の参照には再バインドする</td></tr><tr><td>参照先のデータ</td><td><code>DATA_VOLATILE</code></td><td>CPUからの変更は提出前か実行完了後に行う。GPUの読み書きはバリアなどで同期する</td></tr></tbody></table><p>データのフラグを省略した場合、CBV・SRVは <code>DATA_STATIC_WHILE_SET_AT_EXECUTE</code>、UAVは <code>DATA_VOLATILE</code> として扱われます。サンプラ範囲にはデータ用フラグを付けられず、<code>DESCRIPTORS_VOLATILE</code> と <code>DATA_STATIC</code> は併用できません。例えばフレームごとの定数バッファでは、テーブルのスロットと定数を書いた領域をそれぞれ確保し、記録前に準備して、最後のGPU参照後に両方を再利用する設計にできます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/root-signature-version-1-1#combining-flags" target="_blank" rel="noreferrer">Microsoftの既定値とフラグの組み合わせ</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/fence-based-resource-management" target="_blank" rel="noreferrer">Microsoftのフェンスによる領域管理</a></p>',19)])])}const m=t(s,[["render",i]]);export{g as __pageData,m as default};
